  "r.pallets.stat.vol.v": "482,0 m³",
  "r.pallets.stat.vol.l": "capacidad volumétrica nominal, descontando el contorno del fuselaje (519,6 m³ como prismas)",
  "r.pallets.stat.box.v": "2,9 a 18,8 kg",
